using System;using System.Collections.Generic;using System.Data.SqlClient;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Core { public static class BatchRepository {
 public static List<MedicineBatch> ForMedicine(int medicineId){var a=new List<MedicineBatch>();if(!Database.IsAvailable)return a;try{using(var c=Database.Open())using(var q=new SqlCommand("SELECT Id,MedicineId,BatchNo,ExpiryDate,Quantity,PurchasePrice FROM dbo.MedicineBatches WHERE MedicineId=@m AND Quantity>0 ORDER BY ExpiryDate",c)){q.Parameters.AddWithValue("@m",medicineId);using(var r=q.ExecuteReader())while(r.Read())a.Add(new MedicineBatch{Id=r.GetInt32(0),MedicineId=r.GetInt32(1),BatchNo=r.GetString(2),ExpiryDate=r.GetDateTime(3),Quantity=r.GetInt32(4),PurchasePrice=r.GetDecimal(5)});}}catch{}return a;}
 public static void ConsumeFefo(int medicineId,int qty,SqlConnection c,SqlTransaction tx){var batches=new List<MedicineBatch>();using(var q=new SqlCommand("SELECT Id,MedicineId,BatchNo,ExpiryDate,Quantity,PurchasePrice FROM dbo.MedicineBatches WITH (UPDLOCK,ROWLOCK) WHERE MedicineId=@m AND Quantity>0 AND ExpiryDate>=CAST(GETDATE() AS date) ORDER BY ExpiryDate",c,tx)){q.Parameters.AddWithValue("@m",medicineId);using(var r=q.ExecuteReader())while(r.Read())batches.Add(new MedicineBatch{Id=r.GetInt32(0),MedicineId=r.GetInt32(1),BatchNo=r.GetString(2),ExpiryDate=r.GetDateTime(3),Quantity=r.GetInt32(4),PurchasePrice=r.GetDecimal(5)});}var alloc=FefoService.Allocate(batches,qty);foreach(var b in alloc)using(var u=new SqlCommand("UPDATE dbo.MedicineBatches SET Quantity=Quantity-@q WHERE Id=@id",c,tx)){u.Parameters.AddWithValue("@q",b.Quantity);u.Parameters.AddWithValue("@id",b.Id);u.ExecuteNonQuery();}}
 } }